import{_ as d,a0 as s,w as l,s as p,I as e,x as t,a1 as n,A as i,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const G=JSON.parse('{"title":"安卓編年史（14）：Android 2.3 Gingerbread——第一次 UI 大變 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（14）：Android 2.3 Gingerbread——第一次 UI 大變 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（14）：Android 2.3 Gingerbread——第一次 UI 大變 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（14）：Android 2.3 Gingerbread——第一次 UI 大變 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/14 - The history of Android","title":"安卓編年史（14）：Android 2.3 Gingerbread——第一次 UI 大變","tag":"The history of Android","desc":""},"relativePath":"The history of Android/14 - The history of Android.md","filePath":"[post].md"}'),u={name:"The history of Android/14 - The history of Android.md"};function g(m,o,f,x,b,T){const r=s("Link");return l(),p("div",null,[o[31]||(o[31]=e("h1",{id:"安卓編年史-14-android-2-3-gingerbread——第一次-ui-大變",tabindex:"-1"},[t("安卓編年史（14）：Android 2.3 Gingerbread——第一次 UI 大變 "),e("a",{class:"header-anchor",href:"#安卓編年史-14-android-2-3-gingerbread——第一次-ui-大變","aria-label":"Permalink to “安卓編年史（14）：Android 2.3 Gingerbread——第一次 UI 大變”"},"​")],-1)),o[32]||(o[32]=e("h3",{id:"語音操作——口袋裏的超級電腦",tabindex:"-1"},[t("語音操作——口袋裏的超級電腦 "),e("a",{class:"header-anchor",href:"#語音操作——口袋裏的超級電腦","aria-label":"Permalink to “語音操作——口袋裏的超級電腦”"},"​")],-1)),e("p",null,[o[1]||(o[1]=t("2010 年 8 月，作為語音搜索應用的一項新功能，“",-1)),n(r,{href:"http://arstechnica.com/gadgets/2010/08/google-beefs-up-voice-search-mobile-sync/"},{default:i(()=>[...o[0]||(o[0]=[t("語音命令",-1)])]),_:1}),o[2]||(o[2]=t("”登陸了安卓市場。語音命令允許用户向他們的手機發出語音命令，然後安卓會試着去理解他們並完成任務。像“導航至[地址]”這樣的命令會打開谷歌地圖並且開始逐嚮導航至你所陳述的目的地。你還可以僅僅通過語音來發送短信或電子郵件、撥打電話、打開網站、獲取方向，或是在地圖上查看一個地點。",-1))]),o[33]||(o[33]=e("p",null,"注：youtube視頻地址",-1)),o[34]||(o[34]=e("iframe",{width:"500",height:"281",frameborder:"0",src:"http://www.youtube-nocookie.com/embed/gGbYVvU0Z5s?start=0&wmode=transparent",type:"text/html",style:{display:"block"}},null,-1)),o[35]||(o[35]=e("p",null,"語音命令是谷歌新應用設計哲學的頂峯。語音命令是那時候最先進的語音控制軟件，秘密在於谷歌並不在設備上做任運算。一般來説，語音識別是 CPU 密集型任務。實際上，許多語音識別程序仍然有“速度與準確性”設置，用户可以選擇他們願意為語音識別算法運行等待的時間——更多的 CPU 處理意味着更加準確。",-1)),o[36]||(o[36]=e("p",null,"谷歌的創新在於沒有勞煩手機上能力有限的處理器來進行語音識別運算。當説出一個命令時，用户的聲音會被打包並通過互聯網發送到谷歌雲服務器。在那裏，谷歌超算中心的超級計算機分析並解釋語音，然後發送回手機。這是很長的一段旅程，但互聯網最終還是有足夠快的速度在一兩秒內完成像這樣的任務。",-1)),o[37]||(o[37]=e("p",null,"很多人拋出詞語“雲計算”來表達“所有東西都被存儲在服務器上”，但這才是真正的雲計算。谷歌在雲端進行這些巨量的運算操作，又因為在這個問題上投入了看似荒唐的 CPU 資源數目，所以語音識別準確性的唯一限制就是算法本身了。軟件不需要由每個用户獨立“訓練”，因為所有使用語音操作的人無時不刻都在訓練它。藉助互聯網的力量，安卓在你的口袋裏放了一部超級電腦，同時相比於已有的解決方案，把語音識別這個工作量從口袋大小的電腦轉移到房間大小的電腦上大大提高了準確性。",-1)),e("p",null,[o[4]||(o[4]=t("語音識別作為谷歌的項目已經有一段時間了，它的出現都是因為一個 800 號碼。",-1)),n(r,{href:"http://arstechnica.com/business/2007/04/google-rolls-out-free-411-service/"},{default:i(()=>[...o[3]||(o[3]=[t("1-800-GOOG-411",-1)])]),_:1}),o[5]||(o[5]=t("是個谷歌從 2007 年 4 月起開通的免費電話信息服務。它就像 411 信息服務一樣工作了多年——用户可以撥打這個號碼詢問電話號碼——但是谷歌免費提供這項服務。查詢過程中沒有人工的干預，411 服務由語音識別和文本語音轉換引擎驅動。在人們教谷歌如何去聽之後，又用了三年才有實現語音命令的可能。",-1))]),e("p",null,[o[7]||(o[7]=t("語音識別是谷歌長遠思考的極佳範例——公司並不怕在一個可能成不了商業產品的項目上投資多年。今天，語音識別驅動的產品遍佈谷歌。它被用在谷歌搜索應用的輸入，安卓的語音輸入，以及 Google.com。同時它還是 Google Glass 和 ",-1)),n(r,{href:"http://arstechnica.com/gadgets/2014/03/in-depth-with-android-wear-googles-quantum-leap-of-a-smartwatch-os/"},{default:i(()=>[...o[6]||(o[6]=[t("Android Wear",-1)])]),_:1}),o[8]||(o[8]=t(" 的默認輸入界面。",-1))]),o[38]||(o[38]=e("p",null,"谷歌甚至還在輸入之外的地方使用語音識別。谷歌的語音識別技術被用在了轉述 Youtube 視頻上，它能自動生成字幕供聽障用户觀看。生成的字幕甚至被谷歌做成了索引，所以你可以搜索某句話在視頻的哪裏説過。語音是許多產品的未來，並且這項長期計劃將谷歌帶入了屈指可數的擁有自家語音識別服務的公司行列。大部分其它的語音識別產品，像蘋果的 Siri 和三星設備，只能使用 Nuance 的語音識別，並且為其支付了授權費。",-1)),e("p",null,[o[11]||(o[11]=t("在計算機聽覺系統設立運行之後，谷歌下一步將把這項策略應用到計算機視覺上。這就是為什麼像 Google Goggles，Google 圖像搜索和 ",-1)),n(r,{href:"http://arstechnica.com/gadgets/2014/02/googles-project-tango-is-a-smartphone-with-kinect-style-computer-vision/"},{default:i(()=>[...o[9]||(o[9]=[t("Project Tango",-1)])]),_:1}),o[12]||(o[12]=t(" 這樣的項目存在的原因。就像 GOOG-411 的那段日子，這些項目還處在早期階段。當",-1)),n(r,{href:"http://arstechnica.com/gadgets/2013/12/google-robots-former-android-chief-will-lead-google-robotics-division/"},{default:i(()=>[...o[10]||(o[10]=[t("谷歌的機器人部門",-1)])]),_:1}),o[13]||(o[13]=t("造出了機器人，它會需要看和聽，谷歌的計算機視覺和聽覺項目會給谷歌一個先機。",-1))]),o[39]||(o[39]=e("p",null,[e("img",{src:"http://cdn.arstechnica.net/wp-content/uploads/2014/03/NS500.png",alt:"Nexus S，第一部三星製造的Nexus手機。"})],-1)),o[40]||(o[40]=e("p",null,[e("em",null,"Nexus S，第一部三星製造的 Nexus 手機。")],-1)),o[41]||(o[41]=e("h3",{id:"android-2-3-gingerbread——第一次-ui-大變",tabindex:"-1"},[t("Android 2.3 Gingerbread——第一次 UI 大變 "),e("a",{class:"header-anchor",href:"#android-2-3-gingerbread——第一次-ui-大變","aria-label":"Permalink to “Android 2.3 Gingerbread——第一次 UI 大變”"},"​")],-1)),o[42]||(o[42]=e("p",null,"Gingerbread（薑餅）發佈於 2010 年 12 月，這已是 2.2 發佈整整七個月之後了。儘管如此，等待是值得的，因為安卓 2.3 整個系統的每個界面幾乎都改變了。這是從安卓 0.9 最初的樣式以來第一次重大的更新。2.3 開始了一系列持續的改進，試着將安卓從醜陋的小鴨子變成能承載它自己的合適的樣子——從美學角度——來對抗 iPhone。",-1)),o[43]||(o[43]=e("p",null,"説到蘋果，六個月前，它發佈了 iPhone 4 和 iOS 4，新增了多任務處理和 Facetime 視頻聊天。微軟同樣也終於重返這場競賽。微軟在 2010 年 11 月發佈了 Windows Phone 7，也進入了智能手機時代。",-1)),o[44]||(o[44]=e("p",null,"安卓 2.3 在界面設計上投入了很多精力，但是由於缺乏方向或設計文檔，許多應用僅僅止步於獲得了一個新的定製主題而已。一些應用用了更扁平的暗色主題，一些用了充滿漸變、活潑的暗色主題，其他應用則是高對比度的白色和綠色組合。儘管 2.3 並沒有做到風格統一，Gingerbread 還是完成了讓系統幾乎每個部分變得更現代化的任務。這同樣是件好事，因為下一個手機版安卓要在將近一年後才到來。",-1)),o[45]||(o[45]=e("p",null,"薑餅的首發設備是 Nexus S，谷歌的第二部旗艦設備，並且是第一部由三星生產的 Nexus 設備。儘管今天我們已經習慣了每年都有更新型號的 CPU，那時候可不是這個樣子。Nexus S 有個 1GHz Cortex A8 處理器，和 Nexus One是一樣的。GPU 從速度來説略微有所變快。Nexus S 稍微比 Nexus One 大一點，擁有 800×480 分辨率的 AMOLED 顯示屏。",-1)),o[46]||(o[46]=e("p",null,"從參數上來説，Nexus S 看起來只是個平淡無奇的升級，但它確實開了安卓的許多先河。Nexus S 是谷歌第一部沒有 MicroSD 卡槽的旗艦，板載 16GB 存儲。Nexus One 只有 512MB 存儲空間，但它有 MicroSD 卡槽。移除 SD 卡槽為用户簡化了存儲管理——現在只有一個存儲地點了——但是影響了高級用户的擴展能力。它是谷歌第一部帶有 NFC 的手機，手機背面的一個特殊芯片能夠在和其他 NFC 芯片接觸時傳輸數據。Nexus S 暫時只能讀取 NFC 標籤，而不能發送數據。",-1)),e("p",null,[o[15]||(o[15]=t("託薑餅中一些升級的福，Nexus S 是第一部不帶有硬件十字方向鍵或軌跡球安卓手機之一。Nexus S 縮減到只有電源、音量以及四個導航鍵。Nexus S 同時還是如今",-1)),n(r,{href:"http://arstechnica.com/gadgets/2013/12/lg-g-flex-review-form-over-even-basic-function/"},{default:i(()=>[...o[14]||(o[14]=[t("瘋狂的曲面手機",-1)])]),_:1}),o[16]||(o[16]=t("的先驅，因為三星給 Nexus S 配備了一塊略微有些彎曲的玻璃。",-1))]),o[47]||(o[47]=a("",11)),e("p",null,[n(r,{href:"http://arstechnica.com/author/ronamadeo"},{default:i(()=>[...o[17]||(o[17]=[t("Ron Amadeo",-1)])]),_:1}),o[19]||(o[19]=t(" / Ron是Ars Technica的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1)),n(r,{href:"https://twitter.com/RonAmadeo"},{default:i(()=>[...o[18]||(o[18]=[t("@RonAmadeo",-1)])]),_:1})]),o[48]||(o[48]=e("hr",null,null,-1)),e("p",null,[o[21]||(o[21]=t("via: ",-1)),n(r,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/14/"},{default:i(()=>[...o[20]||(o[20]=[t("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/14/",-1)])]),_:1})]),e("p",null,[o[24]||(o[24]=t("譯者：",-1)),n(r,{href:"https://github.com/alim0x"},{default:i(()=>[...o[22]||(o[22]=[t("alim0x",-1)])]),_:1}),o[25]||(o[25]=t(" 校對：",-1)),n(r,{href:"https://github.com/wxy"},{default:i(()=>[...o[23]||(o[23]=[t("wxy",-1)])]),_:1})]),e("p",null,[o[28]||(o[28]=t("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...o[26]||(o[26]=[t("LCTT",-1)])]),_:1}),o[29]||(o[29]=t(" 原創翻譯，",-1)),n(r,{href:"http://linux.cn/"},{default:i(()=>[...o[27]||(o[27]=[t("Linux中國",-1)])]),_:1}),o[30]||(o[30]=t(" 榮譽推出",-1))])])}const S=d(u,[["render",g]]);export{G as __pageData,S as default};
